package local.generalsmc.client;

import local.generalsmc.GeneralsMod;
import local.generalsmc.nativebridge.WorldResourceStore;
import net.minecraft.client.Minecraft;
import net.minecraft.client.Screenshot;
import net.minecraft.core.BlockPos;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import java.util.*;
import java.util.concurrent.CompletableFuture;

/** Real framebuffer shroud and original audio mixer controlled by actual Minecraft options. */
final class NativeFogAudioBench {
    private static int stage,age,scout,enemy;
    private static long targetCommand;
    private static double master,music,blocks,voice;
    private static CompletableFuture<Void> work;
    static void begin(Minecraft mc,NativeWorldView view,List<String> checks){
        stage=0;age=0;view.fog.enabled(true);view.cameraX=0;view.cameraZ=0;view.zoom=25;
        master=mc.options.getSoundSourceVolume(SoundSource.MASTER);music=mc.options.getSoundSourceVolume(SoundSource.MUSIC);blocks=mc.options.getSoundSourceVolume(SoundSource.BLOCKS);voice=mc.options.getSoundSourceVolume(SoundSource.VOICE);
        work=CompletableFuture.runAsync(()->{var level=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);for(int x=60;x<=142;x++)for(int z=-12;z<=12;z++){level.setBlock(new BlockPos(x,63,z),Blocks.GRASS_BLOCK.defaultBlockState(),3);for(int y=64;y<=67;y++)level.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),3);}},mc.getSingleplayerServer());
    }
    static boolean tick(Minecraft mc,NativeWorldView view,List<String> checks)throws Exception{
        age++;if(age>1400)throw new IllegalStateException("Fog/audio oracle timeout at "+stage);
        if(stage==0&&work.isDone()&&age>120){work.join();if(view.fog.at(0,0)!=0||!view.fog.shaderReady||view.fog.renderedFrames<5)throw new IllegalStateException("Original local base vision or Minecraft fog shader absent");checks.add("Original partition vision keeps the starting base visible and its shroud shader actually renders over Minecraft depth");var p=view.origin.nativePoint(new Vec3(-20.5,64,-20.5));view.session.send("TEST_SPAWN ChinaNuclearMissileLauncher "+p.x+" "+p.y+" 0");view.cameraX=128;view.cameraZ=0;next(1);}
        else if(stage==1&&age>100){if(view.fog.at(128.5,.5)!=255)throw new IllegalStateException("Camera revealed terrain without a scouting unit");checkDimTerrain(mc,view,new Vec3(128.5,64,.5));Screenshot.grab(mc.gameDirectory,"46-original-shroud-unexplored.png",mc.getMainRenderTarget(),c->{});checks.add("Moving the RTS camera into unexplored Minecraft terrain keeps actual terrain dimly visible while original shroud still distinguishes unexplored cells");if(NativeFog.visible(128.5,.5))throw new IllegalStateException("Unexplored resource footprint or mob became visible through shroud");checks.add("Unknown terrain remains visible under dim fog while hidden mobs cannot be picked");targetCommand=powerTarget(view);next(11);}
        else if(stage==11&&view.state.consumed()>=targetCommand){if(targetAllowed(view))throw new IllegalStateException("Original nuclear target oracle permitted unexplored terrain");checks.add("Original ActionManager rejects a nuclear target in unexplored terrain even when its Minecraft chunks are loaded");var p=view.origin.nativePoint(new Vec3(96.5,64,.5));view.session.send("TEST_SPAWN AmericaInfantryRanger "+p.x+" "+p.y+" 0");next(2);}
        else if(stage==2&&age>60){var ranger=view.state.objects().stream().filter(o->o.template().equals("AmericaInfantryRanger")).findFirst().orElseThrow();scout=ranger.id();view.session.select(scout);var p=view.origin.nativePoint(new Vec3(128.5,64,.5));view.session.move(p.x,p.y,p.z);next(3);}
        else if(stage==3&&view.fog.at(128.5,.5)==0&&age>50){var ranger=view.state.objects().stream().filter(o->o.id()==scout).findFirst().orElseThrow();if(view.origin.world(ranger.x(),ranger.y(),ranger.z()).x<105)return false;Screenshot.grab(mc.gameDirectory,"47-original-shroud-scouted.png",mc.getMainRenderTarget(),c->{});checks.add("An original moving Ranger reveals Minecraft terrain through source unit vision while the camera alone does not");var p=view.origin.nativePoint(new Vec3(60.5,64,.5));view.session.move(p.x,p.y,p.z);next(4);}
        else if(stage==4&&view.fog.at(128.5,.5)==160&&age>80){checks.add("Explored terrain becomes original fogged shroud after the scouting unit leaves; it is retained rather than returning to unexplored");targetCommand=powerTarget(view);next(41);}
        else if(stage==41&&view.state.consumed()>=targetCommand){if(!targetAllowed(view))throw new IllegalStateException("Original nuclear target oracle rejected a distant explored target");checks.add("Original ActionManager accepts the distant previously explored nuclear target after the Ranger leaves, without a camera-distance limit; source readiness checked separately");NativeRtsController.toggle();if(!NativeFog.visible(128.5,.5))throw new IllegalStateException("RTS shroud interferes with ordinary Minecraft controls");NativeRtsController.toggle();checks.add("F8 restores ordinary Minecraft visibility without stopping the original match");setVolumes(mc,.6,.25,.5,.75);next(5);}
        else if(stage==5&&age>50){if(!view.state.audioEnabled()||!view.state.hostAudioConfigured()||Math.abs(view.state.musicVolume()-.15)>.01||Math.abs(view.state.soundVolume()-.3)>.01||Math.abs(view.state.speechVolume()-.45)>.01)throw new IllegalStateException("Minecraft options did not control original mixer: "+view.state.musicVolume()+"/"+view.state.soundVolume()+"/"+view.state.speechVolume());checks.add("Actual Minecraft master/music/blocks/voice settings produce original Miles mixer volumes0.15/0.30/0.45 while Generals is unfocused");view.session.send("DEBUG_SOUND DozerUSAVoiceSelect");view.session.send("DEBUG_MUSIC");next(6);}
        else if(stage==6&&age>80){if(!view.state.musicPlaying())throw new IllegalStateException("Original music stream did not start");checks.add("Original BIG music stream plays in the Minecraft-hosted match through its linked music volume");setVolumes(mc,0,.25,.5,.75);next(7);}
        else if(stage==7&&age>50){if(view.state.musicVolume()>.001||view.state.soundVolume()>.001||view.state.speechVolume()>.001)throw new IllegalStateException("Minecraft master mute did not reach every native audio category");checks.add("Minecraft master volume0 mutes original music, speech and effects");setVolumes(mc,.7,1,1,1);view.session.send("DEBUG_MUSIC");next(8);}
        else if(stage==8&&age>350){if(!view.state.musicPlaying()||view.state.musicVolume()<.69)throw new IllegalStateException("Audio did not resume after Minecraft master unmute");checks.add("Original audio resumes after Minecraft unmute; steady music interval available for process-only loopback capture");setVolumes(mc,master,music,blocks,voice);var p=view.origin.nativePoint(new Vec3(128.5,64,.5));view.session.send("TEST_SPAWN ChinaPowerPlant "+p.x+" "+p.y+" "+p.z+" 3");moveScout(view,116.5);next(9);}
        else if(stage==9&&age>100&&view.fog.at(128.5,.5)==0){enemy=view.state.objects().stream().filter(a->a.owner()==3&&a.template().equals("ChinaPowerPlant")&&a.health()>0).findFirst().orElseThrow().id();if(view.scene.batches().stream().noneMatch(b->b.actor()==enemy&&b.count()>0))throw new IllegalStateException("Scouted original enemy building has no rendered geometry");Screenshot.grab(mc.gameDirectory,"82-enemy-building-scouted.png",mc.getMainRenderTarget(),c->{});moveScout(view,60.5);next(10);}
        else if(stage==10&&age>100&&view.fog.at(128.5,.5)==160){if(view.rememberedVertices(enemy)==0)throw new IllegalStateException("Last-seen enemy building disappeared after scout left");checks.add("An actual enemy Power Plant retains its last-seen original mesh under explored fog after the original Ranger leaves");Screenshot.grab(mc.gameDirectory,"83-enemy-building-last-seen.png",mc.getMainRenderTarget(),c->{});view.session.send("TEST_DAMAGE "+enemy+" 1000000");next(12);}
        else if(stage==12&&age>100){if(view.state.objects().stream().anyMatch(a->a.id()==enemy&&a.health()>0)||view.rememberedVertices(enemy)==0)throw new IllegalStateException("Hidden building death leaked through last-seen fog memory");checks.add("Destroying the unseen enemy building does not erase its last-seen mesh or reveal its death to the commander");moveScout(view,116.5);next(13);}
        else if(stage==13&&age>100&&view.fog.at(128.5,.5)==0){if(view.rememberedVertices(enemy)!=0)throw new IllegalStateException("Revealing destroyed enemy building retained its stale mesh");checks.add("Scouting the location again clears the obsolete remembered building mesh");return true;}
        return false;
    }
    private static void setVolumes(Minecraft mc,double m,double music,double blocks,double voice){mc.options.getSoundSourceOptionInstance(SoundSource.MASTER).set(m);mc.options.getSoundSourceOptionInstance(SoundSource.MUSIC).set(music);mc.options.getSoundSourceOptionInstance(SoundSource.BLOCKS).set(blocks);mc.options.getSoundSourceOptionInstance(SoundSource.VOICE).set(voice);}
    private static void checkDimTerrain(Minecraft mc,NativeWorldView view,Vec3 p){var pixel=((NativeWorldScreen)mc.screen).project(p);int x=(int)Math.round(pixel[0]*mc.getWindow().getGuiScale()),y=(int)Math.round(pixel[1]*mc.getWindow().getGuiScale());try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){int c=image.getPixel(x,y);double light=((c&255)+((c>>8)&255)+((c>>16)&255))/3.;if(light<10||light>145)throw new IllegalStateException("Unexplored terrain should remain dimly visible: "+Integer.toHexString(c));}}
    private static void next(int value){stage=value;age=0;GeneralsMod.LOG.info("Fog/audio case {}",stage);}
    private static void moveScout(NativeWorldView view,double x)throws Exception{view.session.select(scout);var p=view.origin.nativePoint(new Vec3(x,64,.5));view.session.move(p.x,p.y,p.z);}
    private static long powerTarget(NativeWorldView view)throws Exception{int launcher=view.state.objects().stream().filter(o->o.template().equals("ChinaNuclearMissileLauncher")).findFirst().orElseThrow().id();var p=view.origin.nativePoint(new Vec3(128.5,64,.5));return view.session.send("TEST_POWER_TARGET "+launcher+" "+p.x+" "+p.y+" "+p.z);}
    private static boolean targetAllowed(NativeWorldView view)throws Exception{return com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(view.session.directory.resolve("power-target-test.json"))).getAsJsonObject().get("allowed").getAsBoolean();}
}
